            videos_needing_remote_lookup: list[str] = []
            for v_url in all_playlist_video_urls:
                m = _VIDEO_ID_REGEX.search(v_url)
                vid = m.group(1) if m else None
                local_chan = local_video_to_channel.get(vid) if vid else None
